LEVELS = ["A1", "A2", "B1", "B2", "C1", "C2"]

def _unit(level: str, n: int, title: str, grammar: list[str], vocab: str) -> CurriculumUnit:
    return CurriculumUnit(
        id=f"yo-{level.lower()}-unit-{n}",
        level=level,
        unit_number=n,
        title=f"Yoruba {level} · {title}",
        grammar_points=grammar,
        vocabulary_set_ids=[vocab],
        lesson_types=["grammar", "vocabulary", "listening", "speaking", "reading", "writing", "review"],
        competency_checklist=["Understand authentic Yoruba input at this level", "Produce accurate Yoruba in context"],
        default_weeks=2,
    )

