def _vocab(level: str, n: int, topic: str, words: list[tuple[str, str, str, str]]) -> VocabularySet:
    return VocabularySet(id=f"yo-{level.lower()}-{n}", level=level, topic=topic, unit_ref=f"yo-{level.lower()}-unit-{n}", words=[VocabularyEntry(word=w, pos=p, definition=d, example=e) for w,p,d,e in words])

