def _units(level: str, titles: list[str], grammar: list[str], vocab_ids: list[str]) -> list[CurriculumUnit]:
    return [_unit(level, i+1, title, [grammar[i % len(grammar)]], vocab_ids[i % len(vocab_ids)]) for i,title in enumerate(titles)]

